/**
 * Upstream API compatibility gate (type level). This file is written against upstream `@laravel/echo-react` 2.x
 * (laravel/echo 2.6.3, fdba6fe): its README and Boost-skill usage and its tests' usage. It must compile UNCHANGED
 * against upstream's built package and against this package's built declarations, so that
 * `@ably/laravel-echo-react` stays a drop-in replacement. Only additive changes are allowed (the intentional
 * differences are runtime only: `ably` is the native Ably connector, D-08, and pusher-js is not injected, P-07),
 * so do not edit this file to make it compile.
 *
 * `pnpm run build && pnpm run test:compat` type-checks it: tests/compat/tsconfig.json maps `@laravel/echo-react`
 * to dist/index.d.ts. It is not a Vitest test file and is not published (`files: ["dist"]`).
 */
/* oxlint-disable no-console -- the README's usage logs the payloads */
import {
    configureEcho,
    echo,
    echoIsConfigured,
    useChannel,
    useConnectionStatus,
    useEcho,
    useEchoModel,
    useEchoNotification,
    useEchoPresence,
    useEchoPublic,
    usePresenceChannel,
    usePublicChannel,
    useSocketId,
    type ConnectionStatus,
} from "@laravel/echo-react";
import { createElement, useEffect, type ReactElement } from "react";

// configureEcho: every driver, with and without explicit options (README, Boost skill, tests/config.test.ts)
configureEcho({ broadcaster: "reverb" });
configureEcho({ broadcaster: "pusher" });
configureEcho({
    broadcaster: "reverb",
    key: "reverb-key",
    wsHost: "localhost",
    wsPort: 8080,
    wssPort: 8080,
    forceTLS: false,
    enabledTransports: ["ws", "wss"],
});
configureEcho({
    broadcaster: "pusher",
    key: "pusher-key",
    cluster: "mt1",
    forceTLS: true,
    authEndpoint: "/broadcasting/auth",
});
configureEcho({ broadcaster: "socket.io", host: "localhost:6001" });
configureEcho({ broadcaster: "mercure", host: "https://hub.test" });
configureEcho({ broadcaster: "null" });
configureEcho({ broadcaster: "ably", key: "ably-key" });

class CustomConnector {
    options: unknown;

    constructor(options: unknown) {
        this.options = options;
    }
}

configureEcho({ broadcaster: CustomConnector, authEndpoint: "/custom/auth" });

// echo() and echoIsConfigured()
const configured: boolean = echoIsConfigured();
const status: ConnectionStatus = echo().connectionStatus();
const socketId: string | undefined = echo().socketId();
const reverbEcho = echo<"reverb">();
reverbEcho.private("orders.1").listen(".OrderShipped", () => {});
reverbEcho.leaveChannel("private-orders.1");
echo().leave("orders.1");
echo().leaveAllChannels();
const configuredOptions = echo().options;
void [configured, status, socketId, configuredOptions];

type OrderData = {
    order: {
        id: number;
        user: { id: number; name: string };
        created_at: string;
    };
};

function OrderTracker({ orderId }: { orderId: number }): ReactElement {
    // README: private channel, return value
    const { leaveChannel, leave, stopListening, listen, channel } = useEcho(
        `orders.${orderId}`,
        "OrderShipmentStatusUpdated",
        (e) => {
            console.log(e);
        },
    );

    stopListening();
    listen();
    leaveChannel();
    leaveChannel(true);
    leave();
    void channel();

    // README: multiple events, typed payload, dependencies and visibility
    useEcho(
        `orders.${orderId}`,
        ["OrderShipmentStatusUpdated", "OrderShipped"],
        (e) => {
            console.log(e);
        },
    );
    useEcho<OrderData>(
        `orders.${orderId}`,
        "OrderShipmentStatusUpdated",
        (e) => {
            const id: number = e.order.id;
            const userId: number = e.order.user.id;
            void [id, userId];
        },
    );
    useEcho<OrderData, "pusher", "public">(
        `orders.${orderId}`,
        ["OrderShipmentStatusUpdated"],
        (e) => console.log(e.order.created_at),
        [orderId],
        "public",
    );
    useEcho<OrderData, "reverb", "presence">(
        `orders.${orderId}`,
        "OrderShipmentStatusUpdated",
        () => {},
        [],
        "presence",
    )
        .channel()
        ?.here(() => {});

    return createElement("div", null, `Tracking order ${orderId}`);
}

function ChatRoom({ roomId }: { roomId: number }): ReactElement {
    useEchoPublic("posts", "PostPublished", (e) => {
        console.log(e);
    });
    useEchoPublic<{ post: { id: number } }>("posts", ["PostPublished"], (e) =>
        console.log(e.post.id),
    );

    // Boost skill: presence callbacks
    const { channel } = useEchoPresence(`chat.${roomId}`, "NewMessage", (e) => {
        console.log(e);
    });

    useEffect(() => {
        channel()?.here((users: unknown) =>
            console.log("Current users:", users),
        );
        channel()?.joining((user: unknown) => console.log(user));
        channel()?.leaving((user: unknown) => console.log(user));
    }, [channel]);

    // Boost skill: client events (whisper)
    const chat = useEcho(`chat.${roomId}`, ["update"], (e) => {
        console.log("Chat event received:", e);
    });

    useEffect(() => {
        chat.channel()?.listenForWhisper("typing", (e: unknown) => {
            console.log(e);
        });
    }, [chat]);

    const handleTyping = () => {
        chat.channel()?.whisper("typing", { name: "Taylor" });
    };
    void handleTyping;

    return createElement("div", null, `Chat room ${roomId}`);
}

function UserProfile({ userId }: { userId: number }): ReactElement {
    // Boost skill and tests: model events
    useEchoModel("App.Models.User", userId, ["UserUpdated"], (e) => {
        console.log(e.model);
    });
    useEchoModel<{ id: number; name: string }, "App.Models.User">(
        "App.Models.User",
        userId,
        [".UserCreated", "UserUpdated"],
        (e) => {
            const name: string = e.model.name;
            const queue: string | null = e.queue;
            void [name, queue];
        },
        [userId],
    );

    // Boost skill and tests: notifications
    const notifications = useEchoNotification(
        `App.Models.User.${userId}`,
        (notification) => {
            console.log(notification.id, notification.type);
        },
    );
    useEchoNotification<{ message: string }>(
        `App.Models.User.${userId}`,
        (notification) => console.log(notification.message),
        ["App.Notifications.InvoicePaid", "App\\Notifications\\Shipped"],
        [userId],
    );
    notifications.stopListening();
    notifications.listen();
    notifications.leaveChannel();

    // channel-only hooks
    const privateChannel = useChannel(`orders.${userId}`);
    privateChannel.channel()?.listen(".OrderShipped", () => {});
    privateChannel.leaveChannel();
    privateChannel.leave();
    useChannel<"pusher", "public">("news", "public");
    usePresenceChannel(`chat.${userId}`)
        .channel()
        ?.here(() => {});
    usePublicChannel("news").leave();

    return createElement("div", null, "User profile");
}

function ConnectionIndicator(): ReactElement {
    const connectionStatus = useConnectionStatus();
    const color: string =
        connectionStatus === "connected"
            ? "green"
            : connectionStatus === "reconnecting"
              ? "orange"
              : "gray";
    const id: string | undefined = useSocketId();

    return createElement(
        "div",
        { style: { color } },
        `Connection: ${connectionStatus} ${id ?? ""}`,
    );
}

void [OrderTracker, ChatRoom, UserProfile, ConnectionIndicator];
